import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';import{tasksForFamily,validFamily,numericFamily,familyGridValid,buildValid,pedigreeValid}from './family-models.js?v=20261023-physicscomplete01';import{showFamily}from './family-visuals.js?v=20261023-physicscomplete01';export{showFamily};
export function mountFamily(l,p,root,{save,done,feedback}){let ts=tasksForFamily(l.widget.slice(7)),w=p.widget;w.familyTask??=ts[0].id;w.familyDrafts??={};w.familyPassed??=[];let i=Math.max(0,ts.findIndex(t=>t.id===w.familyTask)),t=ts[i],v=w.familyDrafts[t.id]??={case:0,answer:'',seen:[]},$=s=>root.querySelector(s),again=()=>mountFamily(l,p,root,{save,done,feedback});syncProcessMovie(l,1,{process:false});p.widgetDone=ts.every(t=>w.familyPassed.includes(t.id));
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(a=>{let v=Array.isArray(a)?a[0]:a,l=Array.isArray(a)?a[1]:a;return `<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`;}).join('')}</select>`;let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('familyCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('familyAnswer','Predict and explain',c[2],v.answer)+'<button class="secondary" id="revealFamily">Reveal evidence →</button><p id="familyReadout" aria-live="polite"></p>';draw=()=>{let revealed=v.revealed===v.case;showFamily(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!revealed});$('#familyReadout').textContent=revealed?c[4]:c[1]+' · Predict, then reveal.';};valid=()=>v.revealed===v.case&&v.answer===c[2][c[3]];}
else if(t.type==='grid'||t.type==='build'){v.cells??=['','','',''];v.rows??=['',''];v.cols??=['',''];let build=t.type==='build',rows=build?v.rows:t.rows,cols=build?v.cols:t.cols,options=t.symbols[0]==='X'?['XX','XY','YY']:[t.symbols[0]+t.symbols[0],t.symbols[0]+t.symbols[1],t.symbols[1]+t.symbols[1]];body='<p>'+(build?'Derive gametes from row parent '+t.rowParent+' and column parent '+t.colParent+'.':'Gamete headers are supplied. Combine each row and column.')+'</p><div style="display:grid;grid-template-columns:minmax(42px,.65fr) 1fr 1fr;gap:8px;align-items:center"><span>↓ / →</span>'+cols.map((c,j)=>build?'<div>'+field('familyCol'+j,'Column gamete '+(j+1),t.symbols,c)+'</div>':'<strong>'+c+'</strong>').join('')+rows.map((r,j)=>(build?'<div>'+field('familyRow'+j,'Row gamete '+(j+1),t.symbols,r)+'</div>':'<strong>'+r+'</strong>')+cols.map((c,k)=>'<div>'+field('familyCell'+(j*2+k),'Cell '+(j+1)+','+(k+1),options,v.cells[j*2+k])+'</div>').join('')).join('')+'</div>';draw=()=>showFamily(t.kind,{title:t.title,rows,cols,cells:v.cells});valid=()=>build?buildValid(v,t):familyGridValid(v,t);}
else if(t.type==='pedigree'){v.people??=['','','',''];body='<p>Recessive model: affected means aa. Both parents and II-2 are unaffected. Infer only what the pedigree establishes.</p>'+['I-1','I-2','II-1','II-2'].map((id,j)=>field('familyPerson'+j,'Genotype of '+id,['AA','Aa','aa','AA or Aa'],v.people[j])).join('');draw=()=>showFamily('pedigree',{title:t.title,people:v.people});valid=()=>pedigreeValid(v);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="familyNumber">Your result / '+t.unit+'</label><input class="lab-input" id="familyNumber" type="number" value="'+(v.number??'')+'">'+field('familyReason','Reasoning',t.reasonChoices,v.reason);draw=()=>showFamily(t.kind,{title:t.title});valid=()=>numericFamily(v.number,t.answer)&&v.reason===t.reasonChoices[t.reason];}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="familyEvidence"></p><div class="lab-actions"><button class="secondary" id="recordFamily">Record reasoning</button><button class="secondary" id="nextFamily">Next challenge →</button></div><p id="familyProgress"></p>';const status=()=>{$('#familyEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.familyPassed.includes(t.id)?'Challenge recorded.':'';$('#familyProgress').textContent=ts.filter(t=>w.familyPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){let change=()=>{let id=el.id,val=el.value;if(id==='familyCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();again();return;}if(id==='familyAnswer')v.answer=val;else if(id==='familyNumber')v.number=val;else if(id==='familyReason')v.reason=val;else if(id.startsWith('familyCell'))v.cells[Number(id.slice(10))]=val;else if(id.startsWith('familyRow'))v.rows[Number(id.slice(9))]=val;else if(id.startsWith('familyCol'))v.cols[Number(id.slice(9))]=val;else if(id.startsWith('familyPerson'))v.people[Number(id.slice(12))]=val;save();draw();};el.onchange=change;if(el.tagName==='INPUT')el.oninput=change;}
if($('#revealFamily'))$('#revealFamily').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();let c=t.cases[v.case];feedback(c[4],v.answer!==c[2][c[3]]);};$('#recordFamily').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.familyPassed.includes(t.id))w.familyPassed.push(t.id);p.widgetDone=ts.every(t=>w.familyPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextFamily').onclick=()=>{if(!w.familyPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.familyTask=ts[(i+1)%ts.length].id;save();again();};}
